const x = session.tensor([2, 3], {
  device,
  requiresGrad: true,
});
const y = session.tensor([5, 7], {
  device,
  requiresGrad: true,
});

const loss = x.mul(y).add(x.mul(x)).sum();
const [dx, dy] = session.grad(loss, [x, y]);

console.log("dx:", Array.from(await dx.toArray()));
console.log("dy:", Array.from(await dy.toArray()));

const a = session.tensor([1, 2, 3, 4, 5, 6], {
  shape: [2, 3],
  device,
  requiresGrad: true,
});
const b = session.tensor([7, 8, 9, 10, 11, 12], {
  shape: [3, 2],
  device,
  requiresGrad: true,
});

const y = a.matmul(b);
const seed = session.tensor([1, 2, 3, 4], { device, shape: [2, 2] });
const [ga, gb] = session.grad(y, [a, b], seed);

// JavaScript observations return flat arrays.
console.log("product:", Array.from(await y.toArray()));

console.log("dA:", Array.from(await ga.toArray()));
console.log("dB:", Array.from(await gb.toArray()));
